window.CA = {"date": "Sunday, 05 July 2026", "updated": "2026-07-05 03:37", "updated_label": "05 Jul 2026, 03:37 IST", "items": [{"title": "PM Modi Inaugurates India's First Greenfield Refinery-Petrochemical Hub in Rajasthan", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "Prime Minister Narendra Modi inaugurated India's first Greenfield refinery and petrochemical hub in Rajasthan on July 4, 2026. The project is a significant addition to India's energy infrastructure, aimed at reducing import dependency and boosting domestic petrochemical production. Modi also inaugurated the new terminal at Jodhpur Airport during the same visit to Rajasthan. He stated that India navigated one of the biggest global energy crises by sourcing energy from over 40 countries, averting a fuel crisis with little burden on citizens.", "exam_angle": "Relevant to GS Paper 3 (Energy Security and Infrastructure); tests knowledge of India's refinery capacity, energy policy, and the government's push for energy self-reliance.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India's first Greenfield refinery-petrochemical hub inaugurated in Rajasthan", "India sourced energy from over 40 countries to avert fuel crisis", "Jodhpur Airport new terminal also inaugurated by PM Modi", "Part of India's broader energy security and infrastructure push"], "source": "NDTV", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "PM Modi Inaugurates Rs 7,600 Crore Semiconductor Plant in Gujarat's Sanand", "category": "scitech", "category_name": "Science & Technology", "summary": "Prime Minister Modi inaugurated a semiconductor manufacturing plant worth Rs 7,600 crore in Sanand, Gujarat on July 4, 2026. The plant is a major milestone under India's semiconductor mission, aimed at building domestic chip manufacturing capability and reducing dependence on imports. Sanand is emerging as a key hub for electronics and semiconductor manufacturing in India. The investment aligns with the India Semiconductor Mission (ISM) under the Ministry of Electronics and Information Technology (MeitY).", "exam_angle": "Directly relevant to GS Paper 3 (Sci-Tech and Economy); tests knowledge of India Semiconductor Mission, Make in India, and critical technology supply chains.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Investment: Rs 7,600 crore", "Location: Sanand, Gujarat", "Inaugurated by PM Modi on July 4, 2026", "Part of India Semiconductor Mission (ISM) under MeitY"], "source": "The New Indian Express", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Parliament Monsoon Session 2026 Scheduled from July 20 to August 13", "category": "polity", "category_name": "Polity & Governance", "summary": "Union Minister Kiren Rijiju announced that the Parliament's Monsoon Session 2026 will commence on July 20 and continue till August 13. Reports indicate the Modi government is eyeing Constitutional amendments during this session. The Lok Sabha Speaker is expected to take decisions on pending anti-defection cases during the session. The session will be closely watched for legislative business including potential amendments.", "exam_angle": "Key for GS Paper 2 (Polity); connects to Parliamentary procedures, Constitutional amendment process (Articles 368), and the anti-defection law (Tenth Schedule).", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Monsoon Session 2026: July 20 to August 13", "Announced by Minister Kiren Rijiju", "Government eyeing Constitutional amendments", "Lok Sabha Speaker to decide on anti-defection cases"], "source": "The Times of India", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "India-UK Free Trade Agreement: Government Notifies Customs Tariff and Rules of Origin", "category": "ir", "category_name": "International Relations", "summary": "The Government of India has notified customs tariff rules for the India-UK Free Trade Agreement (FTA), clearing the way for its rollout from July 15, 2026. The notification includes rules for determination of origin of goods, specifying that no tariff benefits will accrue to repackaged goods. The India-UK FTA is one of the most significant trade deals India has concluded in recent years. India's top three ministers headed to Brussels on a trade mission, with Commerce Minister Goyal also providing updates on FTA progress with Canada, Israel, and Peru.", "exam_angle": "Critical for GS Paper 2 (IR) and GS Paper 3 (Economy); tests knowledge of FTA frameworks, Rules of Origin, and India's trade diplomacy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India-UK FTA customs tariff rules notified", "Rollout date: July 15, 2026", "Rules of Origin notified: no benefits for repackaged goods", "India also in FTA talks with Canada, Israel, and Peru"], "source": "Outlook Business", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Government Sends Takedown Notice to Telegram Over Piracy and Illegal Content", "category": "polity", "category_name": "Polity & Governance", "summary": "The Central Government issued a formal notice to messaging platform Telegram with a 15-day deadline to take immediate action against pirated films, OTT content, and other illegal material being circulated on the platform. This is part of India's enforcement action under the Information Technology Act and copyright laws. The move underscores the government's ongoing crackdown on digital piracy and misuse of social media/messaging platforms. Telegram has previously faced regulatory scrutiny in multiple countries.", "exam_angle": "Relevant to GS Paper 2 (Governance) and GS Paper 3 (Sci-Tech); connects to IT Act provisions, intermediary liability rules, and digital rights enforcement.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Notice issued to Telegram by Government of India", "15-day deadline given for compliance", "Action sought against pirated films and OTT content", "Enforcement under Information Technology Act and copyright law"], "source": "The Times of India", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Centre Allows Four China-Linked Firms to Participate in Critical Power Sector Tenders", "category": "economy", "category_name": "Economy & Banking", "summary": "The Central Government has opened critical power sector bids to four China-linked firms, a decision that has drawn opposition from the Congress party. The move comes amid the broader normalization of India-China economic ties following diplomatic engagement post-Galwan. India's envoy to China also stated that more Chinese investment would be good for the wider bilateral relationship. The decision is significant given India's earlier restrictions on Chinese companies in sensitive sectors post-2020.", "exam_angle": "Relevant to GS Paper 2 (IR) and GS Paper 3 (Economy); connects to India-China relations, FDI policy in critical infrastructure, and national security concerns around Chinese investments.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Four China-linked firms allowed into Indian power sector tenders", "Decision criticized by Opposition (Congress)", "India's envoy to China: more Chinese investment beneficial for bilateral ties", "Reversal of post-2020 restrictions on Chinese firms in sensitive sectors"], "source": "The Hindu", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "India's Ethanol Blending Programme: Government Busts Myths on E20 Petrol Amid Industry Debate", "category": "environment", "category_name": "Environment & Ecology", "summary": "The Government of India issued clarifications busting 10 myths around E20 petrol (20% ethanol blending), addressing concerns about engine damage and excess water usage. India's auto industry defended the ethanol fuel mandate, stating it was implemented through a scientific and phased approach, and that E20 causes no engine damage though mileage may marginally drop. India's Ethanol Blending Programme (EBP) targets 20% blending by 2025-26 as part of energy security and reducing crude oil import dependency. PM Modi also cited the EBP as part of India averting the global energy crisis.", "exam_angle": "Important for GS Paper 3 (Environment and Economy); tests knowledge of India's Ethanol Blending Programme, biofuel policy, and energy security measures.", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["E20 = 20% ethanol blended petrol", "Government busted 10 myths on E20; no engine damage confirmed", "Ethanol Blending Programme target: 20% blending by 2025-26", "EBP aimed at reducing crude oil imports and supporting farmers (sugarcane)"], "source": "NDTV", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Centre Lifts Restrictions on Natural Gas Supplies as Middle East Tensions Ease", "category": "economy", "category_name": "Economy & Banking", "summary": "The Central Government has lifted curbs on natural gas supplies as geopolitical tensions in the Middle East showed signs of easing. This move is expected to stabilize domestic gas availability and moderate prices for industrial and household consumers. Natural gas supply restrictions had been imposed earlier in response to global supply disruptions linked to the Middle East conflict. The decision is part of India's broader energy management strategy to ensure supply security.", "exam_angle": "Relevant to GS Paper 3 (Economy/Energy); tests understanding of India's natural gas policy, LNG imports, and the impact of global geopolitics on India's energy security.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Centre lifts curbs on natural gas supplies", "Reason: easing of Middle East geopolitical tensions", "Move aimed at stabilizing domestic gas prices and availability", "Connects to India's dependence on LNG imports from Middle East"], "source": "NDTV", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Supreme Court SIR Verdict: 23 Opposition Parties Write to Chief Justice of India", "category": "polity", "category_name": "Polity & Governance", "summary": "Twenty-three opposition parties have written to the Chief Justice of India (CJI) regarding the Supreme Court's verdict on the Special Intensive Revision (SIR) of electoral rolls. The SIR process, conducted by the Election Commission, has raised concerns about its implications for citizenship and voting rights. The Supreme Court's verdict on SIR has sparked a national debate on the definition of citizenship versus voter eligibility. The opposition argues the process may disenfranchise eligible voters.", "exam_angle": "Key for GS Paper 2 (Polity); connects to Election Commission's role, electoral rolls, citizenship rights (Article 326), and the right to vote as a constitutional right.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["23 opposition parties wrote to CJI over Supreme Court SIR verdict", "SIR = Special Intensive Revision of electoral rolls by Election Commission", "Concerns raised about disenfranchisement and citizenship definitions", "Connects to Article 326 (right to vote) and Election Commission's powers"], "source": "Frontline Magazine", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Security Forces Kill 2 Terrorists in Anti-Terror Operation in J&K's Shopian", "category": "defence", "category_name": "Defence & Security", "summary": "Security forces launched a major anti-terror operation (CASO – Cordon and Search Operation) in Shopian district of Jammu & Kashmir on July 4, 2026, resulting in the killing of two terrorists. Shopian district in south Kashmir has historically been a militant hotspot. The operation is part of ongoing counter-insurgency efforts in the Kashmir Valley following the Pahalgam attack earlier in 2026. Security forces continue to intensify operations in the region.", "exam_angle": "Relevant to GS Paper 3 (Internal Security); tests knowledge of counter-insurgency operations in J&K, security forces' structure, and the strategic importance of Shopian.", "gs_paper": "GS Paper 3 (defence)", "key_facts": ["2 terrorists killed in Shopian, J&K", "CASO (Cordon and Search Operation) conducted by security forces", "Shopian is in south Kashmir, historically a militant-affected district", "Part of ongoing counter-insurgency operations post-Pahalgam attack"], "source": "The Times of India", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "China Launches Coast Guard Patrols East of Taiwan Amid International Criticism", "category": "ir", "category_name": "International Relations", "summary": "China's coast guard has commenced patrol operations in waters east of Taiwan, which Beijing describes as 'routine law enforcement patrols.' The move has drawn international pushback, with critics viewing it as an escalation of China's assertiveness around Taiwan. The patrols east of Taiwan are significant as they extend China's presence beyond the Taiwan Strait into the Pacific. This development adds to regional tensions in the Indo-Pacific and has implications for India's strategic partnerships.", "exam_angle": "Important for GS Paper 2 (IR); connects to the Taiwan Strait issue, China's maritime assertiveness, UNCLOS, and India's Indo-Pacific strategy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["China launched coast guard patrols east of Taiwan Island", "Beijing terms it 'routine law enforcement patrols'", "Draws international criticism and pushback", "Significant escalation in Indo-Pacific maritime tensions"], "source": "Reuters", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Germany Expresses Concern Over Reports of China Training Russian Troops", "category": "ir", "category_name": "International Relations", "summary": "Germany has described as 'deeply disturbing' reports that China is training Russian military troops, a development that would mark a significant deepening of China-Russia military cooperation. The reports come amid the ongoing Russia-Ukraine conflict, where Western nations have been concerned about Chinese support for Russia. If confirmed, such training would represent a major shift in the China-Russia strategic relationship and would have significant implications for NATO and global security architecture. Russia also warned Ukraine that its attacks 'will not go unanswered.'", "exam_angle": "Relevant to GS Paper 2 (IR); connects to China-Russia relations, NATO-Russia conflict dynamics, and India's strategic balancing between Russia and the West.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Germany called reports of China training Russian troops 'deeply disturbing'", "Concerns raised amid ongoing Russia-Ukraine conflict", "Would mark deepening of China-Russia military cooperation", "Russia warned Ukraine attacks 'will not go unanswered'"], "source": "NDTV", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "US Department of Justice Drops Charges Against Adani Group, Says Case 'Should Never Have Been Brought'", "category": "economy", "category_name": "Economy & Banking", "summary": "The United States Department of Justice (DoJ) has formally dropped charges against the Adani Group, stating the case 'should never have been brought' and that 'not a single penny was lost.' The DoJ also stated that 'courts cannot second-guess prosecutors' in explaining the decision. The Adani Group had been charged with alleged bribery in a US indictment filed in November 2024 related to solar energy contracts. The dropping of charges is a significant development for Adani Group's global business operations and investor sentiment.", "exam_angle": "Relevant to GS Paper 3 (Economy) and GS Paper 2 (IR); connects to India-US economic relations, corporate governance, and the functioning of US judicial/prosecutorial systems.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["US DoJ dropped charges against Adani Group", "DoJ statement: case 'should never have been brought'", "DoJ: 'not a single penny was lost'", "Original charges (Nov 2024) related to alleged bribery in solar energy contracts"], "source": "NDTV", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "India's Top Ministers Head to Brussels for Trade Mission; FTA Updates on Canada, Israel, Peru", "category": "ir", "category_name": "International Relations", "summary": "India's top three cabinet ministers embarked on a trade mission to Brussels, Belgium, signaling active engagement with the European Union on trade and economic cooperation. Commerce Minister Piyush Goyal provided updates on the status of Free Trade Agreement (FTA) negotiations with Canada, Israel, and Peru. The Brussels visit is significant as India and the EU are engaged in ongoing FTA negotiations. India's multi-front trade diplomacy reflects its effort to diversify export destinations and reduce tariff barriers.", "exam_angle": "Relevant to GS Paper 2 (IR) and GS Paper 3 (Economy); tests knowledge of India's FTA strategy, India-EU trade relations, and multilateral economic diplomacy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India's top 3 ministers on trade mission to Brussels (EU)", "Commerce Minister Goyal updated on FTA talks with Canada, Israel, Peru", "India-EU FTA negotiations ongoing", "Part of India's broader multi-front trade diplomacy strategy"], "source": "The Economic Times", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Health Groups Demand Overhaul of India's National List of Essential Medicines (NLEM)", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "Health advocacy groups have demanded a comprehensive overhaul of India's National List of Essential Medicines (NLEM), citing outdated inclusions and omissions of newer critical drugs. The NLEM serves as the basis for price regulation under the Drug Price Control Order (DPCO) administered by the National Pharmaceutical Pricing Authority (NPPA). Advocates are calling for inclusion of newer medicines for non-communicable diseases, anti-cancer drugs, and vaccines. The last major revision of the NLEM was in 2022.", "exam_angle": "Relevant to GS Paper 2 (Health Governance); connects to NLEM, DPCO, NPPA, and India's pharmaceutical pricing and access to medicines policy.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["NLEM = National List of Essential Medicines", "Regulated under Drug Price Control Order (DPCO) by NPPA", "Last major revision: 2022", "Demand: include newer drugs for NCDs, cancer, vaccines"], "source": "The Hindu", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Government Plans Cybersecurity Norms for Connected Vehicles Including Anti-Hijacking and OTA Update Rules", "category": "scitech", "category_name": "Science & Technology", "summary": "The Government of India is planning to introduce regulations to address cybersecurity risks in increasingly connected and smart vehicles, including measures to prevent digital hijacking and standards for over-the-air (OTA) software updates. As modern vehicles incorporate internet connectivity and software-defined systems, they become vulnerable to cyberattacks. The proposed norms are being developed by the Ministry of Road Transport and Highways. This initiative aligns with global regulatory trends for connected and autonomous vehicle security.", "exam_angle": "Relevant to GS Paper 3 (Sci-Tech and Infrastructure); connects to cybersecurity policy, connected vehicles, and India's evolving regulatory framework for emerging technologies.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Ministry of Road Transport and Highways to introduce connected vehicle cybersecurity norms", "Covers anti-hijacking measures and OTA (over-the-air) software update standards", "Addresses risks from smart/internet-connected vehicles", "Aligns with global regulatory trends for autonomous and connected vehicles"], "source": "The Times of India", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "Delhi Court Sentences BJP MLA Raju Kumar Singh to Four-Year Jail in Celebratory Firing Murder Case", "category": "polity", "category_name": "Polity & Governance", "summary": "A Delhi court sentenced BJP MLA Raju Kumar Singh to four years of imprisonment in a celebratory firing murder case. The case involves death caused by celebratory gunfire, a recurring public safety concern in India. The conviction of a sitting Member of the Legislative Assembly is significant from the perspective of the Representation of the People Act, which deals with disqualification of elected representatives upon conviction. The sentence could trigger disqualification proceedings under Section 8 of the RPA, 1951.", "exam_angle": "Important for GS Paper 2 (Polity); connects to disqualification of elected representatives (Section 8, RPA 1951), elected officials' accountability, and criminal law.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["BJP MLA Raju Kumar Singh sentenced to 4 years imprisonment", "Case: celebratory firing leading to murder in Delhi", "Under RPA 1951 (Section 8), conviction with 2+ years triggers disqualification", "Court: Delhi; significant for legislative accountability"], "source": "The New Indian Express", "day": "2026-07-05", "day_label": "05 Jul"}, {"title": "MHA Designates 23 Pakistan-Based Individuals as Terrorists Under UAPA", "category": "polity", "category_name": "Polity & Governance", "summary": "The Ministry of Home Affairs (MHA) has designated 23 Pakistan-based individuals as terrorists under the Unlawful Activities (Prevention) Act (UAPA). The list includes operatives of Jaish-e-Mohammed and Lashkar-e-Taiba, among them Hafiz Saeed's son-in-law and an individual linked to reconnoitring the Ram Temple. The designations cite connections to attacks in Jammu & Kashmir. This is part of India's post-Pahalgam attack crackdown on cross-border terror networks.", "exam_angle": "Tests knowledge of UAPA provisions (Sections 35-36 on terrorist designation), the role of MHA in internal security, and India's counter-terrorism legal framework. Also relevant to India-Pakistan relations and J&K security.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["23 individuals designated terrorists under UAPA by MHA", "Includes Jaish-e-Mohammed and Lashkar-e-Taiba operatives", "Hafiz Saeed's son-in-law included in the list", "UAPA Sections 35-36 govern individual terrorist designation in India"], "source": "The Hindu", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "Monsoon Session of Parliament 2026 to Begin July 20, Conclude August 13", "category": "polity", "category_name": "Polity & Governance", "summary": "The Monsoon Session of the Indian Parliament has been scheduled to commence on July 20, 2026, and will run until August 13, 2026. This is one of the three regular sessions of Parliament held annually. The session is expected to see significant legislative business including pending Bills and budgetary discussions. The dates were confirmed by government sources.", "exam_angle": "Parliamentary sessions are a standard polity topic; aspirants must know the three sessions (Budget, Monsoon, Winter) and the constitutional provisions for summoning Parliament (Article 85). The Monsoon Session often passes key legislation.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Monsoon Session 2026: July 20 to August 13", "Parliament summoned under Article 85 by President on advice of Cabinet", "Three regular sessions: Budget (Feb–May), Monsoon (Jul–Aug), Winter (Nov–Dec)", "Gap between two sessions cannot exceed six months (constitutional requirement)"], "source": "The Times of India", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "India's Indus Waters Treaty Stand Unchanged Amid Pakistan Threats", "category": "ir", "category_name": "International Relations", "summary": "India has reaffirmed that its position on the Indus Waters Treaty (IWT) remains unchanged despite threats from Pakistan following heightened bilateral tensions post-Pahalgam attack. India had earlier served notice to renegotiate or suspend the treaty. An Indian envoy also stated there is no need for India to emulate Pakistan's role in Iran mediation. The stand reflects India's hardened diplomatic posture towards Pakistan.", "exam_angle": "The Indus Waters Treaty (1960, World Bank-brokered) is a perennial GS Paper 2 topic on India-Pakistan relations and river-water disputes. The current suspension/renegotiation controversy is highly exam-relevant.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Indus Waters Treaty signed in 1960, brokered by World Bank", "India served notice to renegotiate IWT after Pahalgam attack 2025", "India's current stand: position on IWT 'unchanged'", "Treaty allocates eastern rivers (Ravi, Beas, Sutlej) to India; western rivers (Indus, Jhelum, Chenab) to Pakistan"], "source": "NDTV", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "Iran: Ayatollah Khamenei's State Funeral Held in Tehran", "category": "ir", "category_name": "International Relations", "summary": "Iran held a weeklong state funeral for Supreme Leader Ayatollah Ali Khamenei in Tehran, with millions of mourners gathering for the procession. Khamenei, who led Iran since 1989, died following a US-Israel military strike on Iran's nuclear and military infrastructure. The funeral comes at a critical juncture for the West Asian region, with Iran's political succession now a major geopolitical concern. US President Trump also commented on the strikes that led to his death.", "exam_angle": "Iran's Supreme Leader position (Velayat-e-Faqih system), Iran's nuclear programme, and West Asia geopolitics are important IR topics. India's energy security via Strait of Hormuz is a GS Paper 3 linkage.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Ayatollah Ali Khamenei was Iran's Supreme Leader since 1989", "Iran's political system: Supreme Leader (Velayat-e-Faqih) is highest authority above President", "India imports significant crude oil from the Gulf region via Strait of Hormuz", "Khamenei's death has created a major geopolitical power vacuum in West Asia"], "source": "The Hindu", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "India's Forex Reserves Fall $5.65 Billion Amid Iran War Fallout", "category": "economy", "category_name": "Economy & Banking", "summary": "India's foreign exchange reserves declined by $5.65 billion, attributed to the impact of the Iran-Israel conflict on global oil prices and financial markets. Rising crude oil import costs are straining India's current account. The rupee also weakened against the dollar in the same period. India navigated the Strait of Hormuz energy crisis with measures described by PM Modi as keeping citizen burden minimal.", "exam_angle": "Forex reserves management, current account deficit, and energy import vulnerability are core GS Paper 3 economy topics. The Hormuz crisis linkage also connects to India's energy security policy.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Forex reserves fell by $5.65 billion due to Iran war impact", "India's forex reserves managed by RBI", "Strait of Hormuz: ~20% of global oil trade passes through it", "Rupee weakened amid global uncertainty; Sensex rallied for 4th consecutive week"], "source": "The Times of India", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "India Sets $1 Trillion Export Target for FY2026 as Trade Rises", "category": "economy", "category_name": "Economy & Banking", "summary": "India has set an ambitious $1 trillion export target for FY2025-26 as both merchandise and services trade showed an upward trend. The government is counting on strong services exports (particularly IT and business services) and a recovering global demand for goods to meet this goal. Commerce Minister Piyush Goyal also indicated that an India-Peru Free Trade Agreement is not imminent. The target aligns with India's broader goal of becoming a major global trading nation.", "exam_angle": "India's export targets, trade policy, and FTA strategy are important for GS Paper 3. The $1 trillion target and the composition of India's export basket (merchandise vs services) are likely MCQ/mains data points.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India's export target for FY26: $1 trillion (merchandise + services combined)", "India's services exports driven by IT, BPO, and professional services", "India-Peru FTA: Commerce Minister says not happening anytime soon", "Ministry of Commerce and Industry oversees India's export promotion"], "source": "The Times of India", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "India-France Economic and Financial Dialogue Co-Chaired by Nirmala Sitharaman in Aix-en-Provence", "category": "ir", "category_name": "International Relations", "summary": "Finance Minister Nirmala Sitharaman co-chaired the India-France Economic and Financial Dialogue (EFD) with French Minister Roland Lescure in Aix-en-Provence, France. The dialogue covered bilateral economic cooperation, investment flows, digital finance, and industrial partnership. France is one of India's key strategic partners in Europe and a member of the G7. The EFD is a high-level bilateral mechanism for economic coordination.", "exam_angle": "India-France bilateral relations, strategic partnership mechanisms, and financial diplomacy are relevant to GS Paper 2 (IR). France is also a key partner in India's defence procurement and nuclear energy cooperation.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India-France EFD co-chaired by Nirmala Sitharaman and Roland Lescure", "Venue: Aix-en-Provence, France", "India and France have a Strategic Partnership since 1998", "France is a key partner in defence (Rafale jets, submarines) and nuclear energy"], "source": "PIB", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "Centre Clears Four China-Linked Firms for Critical Power Sector Tenders", "category": "economy", "category_name": "Economy & Banking", "summary": "The Central government has allowed four Chinese-linked firms to participate in critical power sector tenders, reversing earlier restrictions that blocked Chinese companies from strategic infrastructure projects. The move has drawn political opposition from Congress, which termed it a security risk. India had tightened FDI rules from China in 2020 under Press Note 3, requiring government approval for investments from border-sharing nations. India's envoy to China simultaneously noted that more Chinese investment is beneficial for the broader relationship.", "exam_angle": "India's FDI policy vis-à-vis China (Press Note 3, 2020), energy sector security, and India-China economic relations are high-priority GS Paper 3/IR topics. The tension between economic pragmatism and national security is a key mains theme.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Centre allowed 4 Chinese-linked firms into power sector tenders", "Press Note 3 (2020): mandates government approval for FDI from countries sharing land borders with India", "India-China FDI normalisation linked to post-Galwan disengagement process", "India's envoy to China stated more Chinese investment is good for bilateral ties"], "source": "The Hindu", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "India Investigates Tata Data Leak Exposing Apple iPhone Manufacturing Secrets", "category": "scitech", "category_name": "Science & Technology", "summary": "Indian authorities are investigating a significant data breach at Tata Electronics, which manufactures Apple iPhones in India, that exposed sensitive production and supply chain secrets. The leak raised concerns about the security of India's electronics manufacturing ecosystem, which is being positioned as an alternative to China under the PLI scheme. The incident has implications for Apple's vendor confidentiality and India's credibility as a global electronics hub. Tata Electronics is one of the first Indian companies to manufacture iPhones.", "exam_angle": "India's electronics PLI scheme, Make in India, data security, and the role of Tata/Apple partnership in boosting domestic manufacturing are relevant to GS Paper 3. Data protection laws (DPDP Act 2023) are also a linkage.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Data breach at Tata Electronics exposed Apple iPhone manufacturing secrets", "Tata Electronics: first Indian company to manufacture iPhones (from 2023)", "India's PLI scheme for mobile manufacturing aims to attract global supply chains", "Digital Personal Data Protection Act (DPDP) 2023 governs data security in India"], "source": "The Hindu", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "Government Considers Separate Legal Framework for Artificial Intelligence", "category": "scitech", "category_name": "Science & Technology", "summary": "The Indian government is evaluating the creation of a separate legal framework for Artificial Intelligence (AI), with the IT Secretary indicating that evolving AI technology and risks such as deepfakes, cyber threats, and algorithmic bias may necessitate dedicated legislation. Currently, AI is regulated under existing IT laws and sector-specific guidelines. The Ministry of Electronics and IT (MeitY) has already issued non-binding AI advisory guidelines. India has so far preferred a 'light-touch' regulatory approach to AI.", "exam_angle": "AI regulation, digital governance, and India's technology policy are increasingly important for GS Paper 3. The contrast between India's non-binding advisory approach and the EU AI Act's binding framework is a relevant comparative angle.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Government considering a separate AI law; currently regulated under IT Act 2000", "MeitY issued AI advisory (April 2024) requiring government approval for AI tools in testing phase", "Key AI risks cited: deepfakes, cyber threats, algorithmic bias", "EU AI Act (2024) is the world's first comprehensive binding AI law — contrast with India's approach"], "source": "The Times of India", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "MIB Sends 15-Day Notice to Telegram to Curb Pirated Content", "category": "polity", "category_name": "Polity & Governance", "summary": "The Ministry of Information and Broadcasting (MIB) has issued a notice to the messaging platform Telegram, setting a 15-day deadline to take proactive measures against pirated content circulating on its platform. MIB has sought an action report from Telegram on steps taken to prevent copyright infringement. This is part of India's intensified crackdown on digital piracy, which affects the film, music, and publishing industries. The action falls under the Copyright Act and IT Act provisions.", "exam_angle": "Digital regulation, intermediary liability, and copyright enforcement are important for GS Paper 3 (Sci-Tech/Economy). The role of MIB and India's evolving digital content governance framework are relevant policy dimensions.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Ministry of Information and Broadcasting (MIB) issued notice to Telegram", "15-day deadline to curb pirated content and submit action report", "Telegram has over 900 million global users; widely used for content sharing in India", "IT Act 2000 (intermediary liability) and Copyright Act 1957 are the relevant legal frameworks"], "source": "The Times of India", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "India Removes Chinese Battery-Linked Apps After E-Rickshaw Hack Incident", "category": "scitech", "category_name": "Science & Technology", "summary": "The Indian government ordered the removal of Chinese-origin battery management apps after a Bluetooth-based hack allowed pranksters to remotely disable e-rickshaws in Delhi, stalling traffic and reducing driver earnings. Affected e-rickshaw drivers saw daily earnings drop from ₹1,000 to ₹600. The apps were linked to lithium battery management systems sourced from China. The incident has renewed scrutiny of Chinese software embedded in Indian mobility infrastructure.", "exam_angle": "Cybersecurity vulnerabilities in critical infrastructure, India's dependency on Chinese hardware/software in EVs, and data security policy are GS Paper 3 themes. The incident also highlights EV ecosystem regulation gaps.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Chinese battery management apps removed after Bluetooth hack disabled Delhi e-rickshaws", "Hack reduced e-rickshaw driver earnings from ₹1,000 to ₹600/day", "Apps linked to lithium battery systems sourced from China", "Raises questions about cybersecurity in India's EV/mobility infrastructure"], "source": "The Hindu", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "PM Modi Launches India's First Greenfield Refinery-Petrochemical Complex in Rajasthan", "category": "economy", "category_name": "Economy & Banking", "summary": "Prime Minister Narendra Modi inaugurated India's first Greenfield integrated refinery and petrochemical hub in Rajasthan, marking a significant milestone in India's energy and chemical manufacturing ambitions. The complex is expected to reduce India's dependence on imported petrochemicals and strengthen the domestic chemicals industry. PM Modi also stated that India navigated the Strait of Hormuz energy crisis with minimal burden on citizens, citing strategic petroleum reserves and fuel pricing measures.", "exam_angle": "India's energy security, refinery capacity, petrochemical industry under Make in India, and strategic petroleum reserves are GS Paper 3 topics. Greenfield vs brownfield investment concepts are also relevant.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India's first Greenfield refinery-petrochemical complex inaugurated in Rajasthan by PM Modi", "Aims to reduce India's reliance on imported petrochemicals", "India maintains Strategic Petroleum Reserves (SPR) at Visakhapatnam, Mangaluru, and Padur", "India is the world's third-largest oil consumer and importer"], "source": "NDTV", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "A New Chapter in India's Nuclear Journey: PIB", "category": "scitech", "category_name": "Science & Technology", "summary": "The Press Information Bureau (PIB) published a feature titled 'A New Chapter in India's Nuclear Journey,' highlighting recent developments in India's civilian nuclear energy programme. India is expanding its nuclear capacity as part of its low-carbon energy transition, with plans to increase nuclear power share in the electricity mix. The Department of Atomic Energy (DAE) oversees India's nuclear programme, which includes NPCIL-run reactors and indigenous development of Pressurised Heavy Water Reactors (PHWRs).", "exam_angle": "India's nuclear energy policy, the three-stage nuclear programme, NPCIL, and nuclear as part of India's clean energy transition are important GS Paper 3 (Energy/Sci-Tech) topics. India's nuclear doctrine and safeguards are also relevant.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["India's nuclear programme governed by Department of Atomic Energy (DAE)", "Three-stage nuclear programme: PHWRs → Fast Breeder Reactors → Thorium-based reactors", "NPCIL operates civilian nuclear power plants", "India has ~7,480 MW installed nuclear capacity (about 3% of electricity mix); target to expand significantly"], "source": "PIB", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "Sri Lanka Upgraded to Upper-Middle Income; India's Classification Unchanged Despite Growth", "category": "economy", "category_name": "Economy & Banking", "summary": "The World Bank has reclassified Sri Lanka as an upper-middle-income country, a significant economic milestone following the island nation's recovery from its 2022 debt crisis. India, despite strong GDP growth of 7-8% as noted by US President Trump, remains classified as a lower-middle-income country. The World Bank uses Gross National Income (GNI) per capita thresholds for income classification, reviewed annually. India's large population keeps its per capita income below the upper-middle threshold.", "exam_angle": "World Bank income classifications, GNI per capita thresholds, and India's position in global economic rankings are standard GS Paper 3 data points. The contrast between GDP growth rate and per capita income is an important conceptual distinction.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["World Bank income groups: Low (<$1,145 GNI/capita), Lower-Middle ($1,146–$4,515), Upper-Middle ($4,516–$14,005), High (>$14,005)", "Sri Lanka reclassified as Upper-Middle Income country", "India remains Lower-Middle Income despite ~7-8% GDP growth", "Trump acknowledged India growing at 7-8%, walked back earlier 'dead economy' remark"], "source": "Moneycontrol", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "Tech Layoffs in First Half of 2026 Exceed All of 2025; India Second-Worst Hit", "category": "economy", "category_name": "Economy & Banking", "summary": "Global technology sector layoffs in the first half of 2026 have already surpassed the total layoffs recorded throughout all of 2025, according to a new report. India is the second-worst affected country globally after the United States, with thousands of IT sector employees losing jobs amid automation, AI-driven workforce restructuring, and cost-cutting by major tech firms. Simultaneously, AI-focused hiring is outpacing overall IT recruitment in India, creating a skills mismatch.", "exam_angle": "Structural unemployment, technology-driven job displacement, India's IT sector dependence, and the AI-employment paradox are relevant GS Paper 3 (Economy/Sci-Tech) themes important for essay and mains answers.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["H1 2026 tech layoffs globally exceed entire 2025 total", "India is second-worst affected country after the US in tech layoffs", "AI hiring in India outpacing overall IT sector recruitment (separate report)", "43% of Indian firms use AI but workforce readiness still lags (India Today report)"], "source": "NDTV", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "First Season's Low-Pressure Area Forms Over Bay of Bengal; Red Alerts Issued for Odisha and Mumbai", "category": "environment", "category_name": "Environment & Ecology", "summary": "The India Meteorological Department (IMD) reported the formation of the season's first low-pressure area over the Bay of Bengal, triggering heavy rainfall warnings. Red alerts were issued for five districts in Odisha, and Mumbai was placed on red alert for extremely heavy rainfall. IMD also issued rain warnings for Konkan and the Western Ghats. Low-pressure areas over the Bay of Bengal are a primary mechanism driving monsoon rainfall over the Indian subcontinent.", "exam_angle": "Monsoon meteorology, the role of the Bay of Bengal in driving Indian monsoon, IMD warning systems (colour-coded alerts), and disaster preparedness are important GS Paper 1/3 topics. Low-pressure areas and cyclogenesis are standard geography concepts.", "gs_paper": "GS Paper 1 (Geography)", "key_facts": ["Season's first low-pressure area formed over Bay of Bengal (July 2026)", "IMD red alert issued for 5 Odisha districts and Mumbai", "IMD colour-coded alerts: Green (no warning), Yellow (watch), Orange (alert), Red (warning — take action)", "Bay of Bengal supplies moisture for ~80% of India's monsoon rainfall"], "source": "The Hindu", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "Europe Heatwave 2026: France Reports 30% Rise in Deaths as Temperatures Shatter Records", "category": "environment", "category_name": "Environment & Ecology", "summary": "Europe is experiencing a severe heatwave in 2026, with France reporting a 30% rise in heat-related deaths compared to previous years as temperatures break historical records. The heatwave is being attributed to climate change-driven shifts in weather patterns, including a weakened jet stream. The event underscores the accelerating frequency and intensity of extreme heat events globally, consistent with IPCC projections. European nations have activated emergency heat action plans.", "exam_angle": "Climate change impacts, extreme weather events, urban heat islands, and global warming projections from IPCC are critical GS Paper 3 (Environment) topics. Heat mortality is an important dimension of climate adaptation discourse.", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["Europe heatwave 2026: France reports 30% rise in heat-related deaths", "Linked to climate change-driven jet stream weakening and blocking high-pressure systems", "IPCC AR6 (2021-22): 1.5°C warming threshold increases extreme heat frequency significantly", "Europe's 2003 heatwave killed ~70,000 people — a benchmark for climate mortality studies"], "source": "The Indian Express", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "Notorious Gangster Goldy Dhillon Arrested in Spain", "category": "persons", "category_name": "Persons & Awards in News", "summary": "Goldy Dhillon, a notorious India-origin gangster believed to be operating from abroad and linked to multiple organized crime networks in India, was arrested in Spain. Dhillon is associated with criminal activities including extortion, contract killings, and links to cross-border crime syndicates. The arrest is significant in the context of India's efforts to extradite fugitive criminals from abroad and its growing law enforcement cooperation with European nations. Red Corner Notices through Interpol are typically used in such cases.", "exam_angle": "Extradition treaties, Interpol Red Corner Notices, organized crime and national security, and India's bilateral law enforcement cooperation are GS Paper 3/IR topics. Fugitive criminals abroad is a recurring mains theme.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Goldy Dhillon arrested in Spain; linked to organized crime in India", "India uses Interpol Red Corner Notices to seek arrest of fugitives abroad", "India-Spain do not have a formal extradition treaty; mutual legal assistance possible", "India has extradition treaties with ~50 countries; extradition from non-treaty countries possible via diplomatic channels"], "source": "The Times of India", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "Bengaluru, Chandigarh, Delhi Top India's Average Income Rankings: Report", "category": "reports", "category_name": "Reports & Indices", "summary": "A new report has ranked Bengaluru, Chandigarh, and Delhi as the top cities in India by average per capita income, reflecting the concentration of high-paying IT, government, and services sector jobs in these urban centres. The report highlights the growing urban-rural and inter-city income disparity in India. Bengaluru's position at the top is driven by its status as India's technology capital and startup ecosystem hub. The findings have implications for understanding India's uneven growth pattern.", "exam_angle": "Regional economic disparities, urbanisation, income inequality, and the role of cities in India's economic growth are GS Paper 1/3 themes. Such reports may appear as data sources in mains questions on economic geography.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Top cities by average income: Bengaluru, Chandigarh, Delhi (Report, 2026)", "Bengaluru is India's IT capital and leading startup hub", "India's Gini coefficient indicates moderate-to-high income inequality", "India's urban population: ~36% (Census 2011 data); projected to reach 50% by 2050"], "source": "The Times of India", "day": "2026-07-04", "day_label": "04 Jul"}, {"title": "India-Japan Summit 2026: Both Nations Reaffirm Economic Security Partnership, Focus on Northeast India and AI", "category": "ir", "category_name": "International Relations", "summary": "India and Japan held a bilateral summit in 2026, with both sides reaffirming their shared commitment to economic security as a foundational pillar of the relationship. Commerce Minister Piyush Goyal stated that Japan and India are working together to promote industry in India's Northeast. The two countries also deepened ties on AI and technology, with PM Modi and Japan's Takaichi engaging on digital cooperation. Energy ties were also highlighted as a key area of collaboration.", "exam_angle": "India-Japan bilateral relations are a recurring GS Paper 2 topic; key themes include the Special Strategic and Global Partnership, Act East Policy linkage, and economic security cooperation.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India-Japan Summit held in 2026", "Focus areas: economic security, Northeast India industrialisation, AI & technology, energy", "Commerce Minister Piyush Goyal represented India on economic cooperation", "India-Japan relation status: Special Strategic and Global Partnership"], "source": "NDTV", "day": "2026-07-03", "day_label": "03 Jul"}, {"title": "Defence Acquisition Council Approves Rs 52,000 Crore Military Procurement Including Anti-Drone Systems and Air Defence Missiles", "category": "defence", "category_name": "Defence & Security", "summary": "The Defence Acquisition Council (DAC), chaired by the Defence Minister, approved military procurement worth Rs 52,000 crore. The approved items include anti-drone systems, air defence missiles, and naval equipment. Additionally, 600 Hammer bombs and anti-tank missiles worth approximately Rs 5,000 crore are also in the pipeline for approval. This is part of India's continued push to modernise its armed forces and strengthen indigenous defence manufacturing.", "exam_angle": "DAC approvals are central to India's defence procurement policy and the Atmanirbhar Bharat initiative in defence; relevant to GS Paper 3 (Defence/Security) and GS Paper 2 (Government policies).", "gs_paper": "GS Paper 3 (Defence)", "key_facts": ["DAC approved Rs 52,000 crore worth of military procurement", "Includes: anti-drone systems, air defence missiles, naval equipment", "600 Hammer bombs and anti-tank missiles (Rs ~5,000 crore) also in pipeline", "DAC is chaired by the Defence Minister of India"], "source": "Moneycontrol.com", "day": "2026-07-03", "day_label": "03 Jul"}, {"title": "Monsoon Session of Parliament Scheduled to Begin July 20, 2026", "category": "polity", "category_name": "Polity & Governance", "summary": "The Monsoon Session of the Indian Parliament has been set to commence on July 20, 2026. The session is expected to have a high-stakes legislative agenda. Parliamentary sessions are a key constitutional mechanism for legislative business, Question Hour, and government accountability. The timing aligns with the traditional monsoon session schedule.", "exam_angle": "Parliamentary sessions — Budget, Monsoon, and Winter — are important for Polity; the question of summoning Parliament (Article 85) and the role of sessions in law-making is frequently tested.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Monsoon Session 2026 to begin: July 20", "Parliament is summoned by the President under Article 85 of the Constitution", "Three sessions annually: Budget (Feb), Monsoon (July), Winter (Nov-Dec)"], "source": "News18", "day": "2026-07-03", "day_label": "03 Jul"}, {"title": "Government Orders Removal of Three Chinese Battery Management Apps Used to Remotely Disable E-Rickshaws", "category": "scitech", "category_name": "Science & Technology", "summary": "The Indian government ordered the removal of three Chinese battery management applications that were being used to remotely disable e-rickshaws — effectively acting as a 'kill switch.' The apps could lock the vehicles' batteries via a smartphone interface, creating disruption for drivers. The move is part of broader concerns about Chinese apps with potential security and economic vulnerabilities. The Ministry of Electronics and IT (MeitY) was involved in the action.", "exam_angle": "Connects to cybersecurity, data sovereignty, and regulation of Chinese apps in India (post-2020 ban context); relevant to GS Paper 3 (Sci-Tech/Internal Security) and GS Paper 2 (Government policies).", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["3 Chinese battery management apps ordered to be removed", "Apps used as remote 'kill switch' for e-rickshaw batteries", "MeitY (Ministry of Electronics and IT) involved in action", "Relates to India's ongoing scrutiny of Chinese digital applications"], "source": "Hindustan Times", "day": "2026-07-03", "day_label": "03 Jul"}, {"title": "India Firms Up Position on Indus Waters Treaty Amid Pakistan Threats", "category": "ir", "category_name": "International Relations", "summary": "India has stated that its position on the Indus Waters Treaty (IWT) remains 'unchanged' despite threats from Pakistan. This follows India's suspension/modification of its approach to the treaty after the Pahalgam terror attack in April 2025. India has been asserting its rights over western rivers as well as pushing for treaty renegotiation. Pakistan has raised objections at global forums, with India preparing a strong rebuttal.", "exam_angle": "Indus Waters Treaty (1960, World Bank-mediated) is a perennial IR and environment topic; India-Pakistan water disputes are tested in GS Paper 2 (IR) and GS Paper 3 (Environment).", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Indus Waters Treaty signed in 1960, mediated by the World Bank", "India declared treaty 'in abeyance' following Pahalgam attack (April 2025)", "India reaffirms its stand remains 'unchanged' despite Pakistani pressure", "Treaty allocates eastern rivers to India, western rivers (Indus, Jhelum, Chenab) to Pakistan"], "source": "NDTV", "day": "2026-07-03", "day_label": "03 Jul"}, {"title": "India's Services PMI Falls to 17-Month Low of 57.4 in June 2026 as Demand Softens", "category": "economy", "category_name": "Economy & Banking", "summary": "India's Services Purchasing Managers' Index (PMI) dropped to 57.4 in June 2026, a 17-month low, as demand conditions softened. Despite the decline, any reading above 50 indicates expansion, so the services sector remains in growth territory. The slowdown is attributed to moderation in new business inflows. The Services PMI is compiled by S&P Global and tracks activity in the services sector.", "exam_angle": "PMI is a key economic indicator frequently referenced in GS Paper 3 (Economy); understanding the PMI threshold (50) and its sectoral significance is important for prelims and mains.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India Services PMI: 57.4 in June 2026 (17-month low)", "Any PMI above 50 signals expansion; below 50 signals contraction", "PMI compiled by S&P Global (formerly IHS Markit)", "Decline driven by softening of new business demand"], "source": "The Hindu", "day": "2026-07-03", "day_label": "03 Jul"}, {"title": "New Gold Monetisation Scheme in the Works to Reduce Dependence on Imported Gold", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "The Indian government is working on a revamped Gold Monetisation Scheme aimed at reducing India's heavy dependence on imported gold. The scheme will seek to mobilise idle domestic gold held by households and institutions. India is one of the world's largest gold importers, and the scheme is intended to channel domestic gold into the financial system. Details of the new scheme design are still being finalised.", "exam_angle": "Gold Monetisation Scheme (GMS) was originally launched in 2015; its revision connects to GS Paper 3 (Economy) themes of current account deficit, gold imports, and government schemes.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Original Gold Monetisation Scheme launched in 2015", "New scheme aims to reduce gold import dependence", "India is among the world's top gold importers (approx. 700-800 tonnes/year)", "Scheme mobilises idle household/institutional gold into banking system"], "source": "The Times of India", "day": "2026-07-03", "day_label": "03 Jul"}, {"title": "MeitY Summons Meta Over Instagram Ads Promoting Child Sexual Abuse Material in India", "category": "polity", "category_name": "Polity & Governance", "summary": "A BBC investigation found that Instagram was running advertisements in India that promoted child sexual abuse material (CSAM). IT Minister Ashwini Vaishnaw ordered MeitY to summon Meta to explain the lapse. The incident raises serious concerns about platform accountability under India's IT Rules 2021 and the Information Technology Act. Meta is required to ensure due diligence and content moderation under its obligations as a significant social media intermediary.", "exam_angle": "Relates to IT Act 2000, IT (Intermediary Guidelines) Rules 2021, digital governance and platform accountability — core GS Paper 2 (Polity/Governance) and GS Paper 3 (Sci-Tech) topics.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["BBC investigation revealed Instagram ads promoting CSAM in India", "IT Minister Ashwini Vaishnaw ordered MeitY to summon Meta", "Governed by IT Act 2000 and IT (Intermediary Guidelines) Rules 2021", "Meta (parent of Instagram) is classified as a Significant Social Media Intermediary (SSMI)"], "source": "BBC", "day": "2026-07-03", "day_label": "03 Jul"}, {"title": "India Issues Notices to WhatsApp, Telegram, and Signal Over Anonymity and Username Features", "category": "polity", "category_name": "Polity & Governance", "summary": "After sending a notice to Meta over WhatsApp's new username feature, the Indian government has now issued notices to Telegram and Signal over their anonymity features. The Centre is examining whether these features comply with India's IT Rules 2021, which require significant social media intermediaries to enable traceability of message originators. The move is part of broader concerns about encryption and anonymity enabling illegal activities.", "exam_angle": "Traceability requirements under IT Rules 2021, encryption debate, and intermediary liability are critical GS Paper 2 and GS Paper 3 topics; also connects to Supreme Court's privacy jurisprudence.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Notices issued to WhatsApp, Telegram, and Signal", "Issue: username/anonymity features potentially enabling untraceable communication", "IT (Intermediary Guidelines and Digital Media Ethics Code) Rules 2021 require traceability", "Significant Social Media Intermediaries (SSMIs) must identify first originator of messages"], "source": "The Indian Express", "day": "2026-07-03", "day_label": "03 Jul"}, {"title": "Ethanol-Blended Fuel Row: Government Moves to Quell Public Backlash After 'Experiment' Remark", "category": "economy", "category_name": "Economy & Banking", "summary": "The Indian government moved to manage public backlash over ethanol-blended petrol after a remark describing the blending programme as an 'experiment' sparked controversy. India has a national target of 20% ethanol blending in petrol by 2025-26 under the Ethanol Blended Petrol (EBP) programme. The government reiterated its commitment to the programme, which aims to reduce oil imports, cut emissions, and boost farmer incomes. The blending programme is also aligned with India's energy security and climate goals.", "exam_angle": "Ethanol blending programme is a key GS Paper 3 topic (Economy + Environment); connects to energy security, farm income support, and India's NDC commitments under Paris Agreement.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India's target: 20% ethanol blending in petrol by 2025-26 under EBP Programme", "Ethanol sourced primarily from sugarcane, maize, and damaged food grains", "Programme reduces crude oil imports and lowers vehicular emissions", "Nodal ministry: Ministry of Petroleum and Natural Gas"], "source": "Reuters", "day": "2026-07-03", "day_label": "03 Jul"}, {"title": "Ayatollah Khamenei Dies: India Pays Tribute as Iran Holds State Funeral in Tehran", "category": "ir", "category_name": "International Relations", "summary": "Iran's Supreme Leader Ayatollah Ali Khamenei passed away and was laid in state in Tehran ahead of a weeklong mass funeral. Indian dignitaries paid tribute to the late Iranian Supreme Leader. Khamenei had held the position of Supreme Leader since 1989 following Ayatollah Khomeini. His son Mojtaba Khamenei's absence from the funeral drew attention amid speculation about succession. The development has significant geopolitical implications for West Asia and India-Iran relations.", "exam_angle": "Iran's political structure (Supreme Leader, President, Guardian Council) and India-Iran bilateral relations (Chabahar Port, energy ties) are important GS Paper 2 (IR) topics.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Ayatollah Ali Khamenei: Iran's Supreme Leader since 1989", "Supreme Leader is the highest authority in Iran's theocratic system", "India-Iran ties: Chabahar Port, energy imports, connectivity to Central Asia", "Succession question: Iran's Assembly of Experts appoints the next Supreme Leader"], "source": "The Hindu", "day": "2026-07-03", "day_label": "03 Jul"}, {"title": "France Records 30% Rise in Deaths During June 2026 Heatwave: Report", "category": "environment", "category_name": "Environment & Ecology", "summary": "France reported a 30% rise in deaths during the June 2026 heatwave, according to official data. The heatwave is part of a broader pattern of extreme heat events intensifying across Europe due to climate change. European countries have been witnessing record-breaking temperatures with increasing frequency. The report underscores the public health and mortality dimensions of climate-induced extreme weather events.", "exam_angle": "Heatwaves as a climate change impact, urban heat island effect, and extreme weather mortality are important for GS Paper 3 (Environment) and GS Paper 1 (Geography).", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["France: 30% rise in deaths during June 2026 heatwave", "Heatwaves are classified as extreme weather events linked to climate change", "IPCC reports indicate frequency and intensity of heatwaves increasing globally", "Heat mortality is a key public health concern in the context of climate adaptation"], "source": "NDTV", "day": "2026-07-03", "day_label": "03 Jul"}, {"title": "Russia Purchased Gasoline Produced by India's Nayara Energy via Third-Party Traders: Report", "category": "economy", "category_name": "Economy & Banking", "summary": "Fuel-hit Russia reportedly purchased gasoline produced by India's Nayara Energy through third-party traders, according to media reports. Nayara Energy is a Rosneft-backed refinery based in Vadinar, Gujarat. This development is significant as it reveals the indirect channels through which sanctioned Russia continues to access petroleum products. India has maintained that its energy trade with Russia does not violate any applicable sanctions.", "exam_angle": "India-Russia energy trade, Western sanctions on Russia, and India's strategic autonomy in foreign policy are key GS Paper 2 (IR) and GS Paper 3 (Economy/Energy) topics.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Nayara Energy: major Indian refinery, backed by Russia's Rosneft", "Located in Vadinar, Gujarat; one of India's largest private refineries", "Russia under Western sanctions since 2022 Ukraine invasion", "India maintains energy trade does not violate applicable international sanctions"], "source": "The Times of India", "day": "2026-07-03", "day_label": "03 Jul"}, {"title": "India Investigates Tata Electronics Data Leak That Exposed Apple iPhone Manufacturing Secrets", "category": "scitech", "category_name": "Science & Technology", "summary": "Indian authorities are investigating a data leak from Tata Electronics that reportedly exposed sensitive Apple iPhone manufacturing data and trade secrets. Tata Electronics, a subsidiary of the Tata Group, manufactures iPhones in India as part of Apple's efforts to diversify its supply chain away from China. The breach raises concerns about data security in critical manufacturing supply chains. Apple and Tata Electronics are key players in India's electronics manufacturing ecosystem under the PLI scheme.", "exam_angle": "Connects to India's PLI scheme for electronics manufacturing, data security, cybersecurity law, and supply chain diversification — relevant to GS Paper 3 (Economy/Sci-Tech).", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Tata Electronics manufactures iPhones in India (PLI scheme beneficiary)", "Data leak allegedly exposed Apple iPhone manufacturing secrets", "Investigation underway by Indian authorities", "Apple's India manufacturing: part of China+1 supply chain diversification strategy"], "source": "The Indian Express", "day": "2026-07-03", "day_label": "03 Jul"}, {"title": "Supreme Court Refuses to Cancel Bail of Sonam Raghuvanshi in Meghalaya Honeymoon Murder Case", "category": "polity", "category_name": "Polity & Governance", "summary": "The Supreme Court of India declined to cancel the bail granted to Sonam Raghuvanshi, the accused in the Meghalaya honeymoon murder case. The court maintained that the bail order would continue. The case involves allegations of murder of a husband during a honeymoon trip in Meghalaya. The Supreme Court's decision reflects the high threshold required to cancel bail once granted by a lower court.", "exam_angle": "Bail jurisprudence under CrPC (now BNSS), Supreme Court's appellate powers, and personal liberty under Article 21 are important GS Paper 2 (Polity) and judicial process topics.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Supreme Court refused to stay/cancel bail of Sonam Raghuvanshi", "Case: Meghalaya honeymoon murder — alleged murder of husband", "Bail cancellation requires higher threshold than bail grant (settled SC jurisprudence)", "Relates to Article 21 (Right to Life and Personal Liberty) and bail under BNSS 2023"], "source": "The Indian Express", "day": "2026-07-03", "day_label": "03 Jul"}, {"title": "8th Pay Commission: Projections Show Basic Pay Could Rise from Rs 18,000 to Rs 69,000", "category": "economy", "category_name": "Economy & Banking", "summary": "Speculative projections on the 8th Pay Commission suggest that the minimum basic pay for central government employees could rise from Rs 18,000 to approximately Rs 69,000, implying a fitment factor of around 2.86. The 8th Pay Commission was constituted in January 2025 and is expected to submit its recommendations, which would be implemented from January 2026. The commission reviews pay, allowances, and service conditions of central government employees.", "exam_angle": "Pay Commissions are significant for GS Paper 3 (Economy) — they impact government expenditure, fiscal deficit, and consumption demand; also relevant to governance (GS Paper 2).", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["8th Pay Commission constituted: January 2025", "Implementation expected from: January 2026", "Current minimum basic pay (7th CPC): Rs 18,000", "Projected fitment factor speculation: ~2.86x (implying ~Rs 69,000 minimum basic pay)"], "source": "NDTV", "day": "2026-07-03", "day_label": "03 Jul"}, {"title": "NIFT Mumbai Participates in HGH India 2026 to Showcase Academic and Industry Connect", "category": "culture", "category_name": "Art & Culture", "summary": "The National Institute of Fashion Technology (NIFT) Mumbai participated in HGH India 2026, a leading home, housewares, and gift trade fair, to showcase its academic excellence and industry linkages. NIFT is a statutory body established under the NIFT Act 2006 under the Ministry of Textiles. The participation underscores the role of design education institutions in connecting with India's textile and handicraft industries. HGH India is one of Asia's largest trade fairs for home and lifestyle products.", "exam_angle": "NIFT as a statutory institution under the Ministry of Textiles, and government initiatives linking design education to industry, are relevant for GS Paper 2 (Governance) and GS Paper 1 (Culture/Art).", "gs_paper": "GS Paper 1 (Culture)", "key_facts": ["NIFT: established under NIFT Act 2006, under Ministry of Textiles", "NIFT Mumbai participated in HGH India 2026 trade fair", "HGH India: major trade fair for home, housewares, and gift sector", "NIFT has 19 campuses across India"], "source": "PIB", "day": "2026-07-03", "day_label": "03 Jul"}], "categories": [{"id": "polity", "name": "Polity & Governance"}, {"id": "economy", "name": "Economy & Banking"}, {"id": "ir", "name": "International Relations"}, {"id": "environment", "name": "Environment & Ecology"}, {"id": "scitech", "name": "Science & Technology"}, {"id": "schemes", "name": "Govt Schemes & Policies"}, {"id": "defence", "name": "Defence & Security"}, {"id": "reports", "name": "Reports & Indices"}, {"id": "persons", "name": "Persons & Awards in News"}, {"id": "culture", "name": "Art & Culture"}]};